for (const body of Object.values(BODIES)) for (const language of ["id", "en"]) body[language].limits = body[language].limits.replace("PHRASES", PHRASES[language]);

export const STORIES = CARDS.map((card) => ({ ...card, id: { ...card.id, ...BODIES[card.slug].id }, en: { ...card.en, ...BODIES[card.slug].en }, scenes: BODIES[card.slug].scenes }));
